/**
 * frontend/src/components/Enrollment.jsx - VERSION ATTRACTIVE
 * Logique originale intacte - Seulement design amélioré
 */

import React, { useState } from 'react';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#1E40AF',      // Bleu profond
  primaryLight: '#DBEAFE',
  accent: '#10B981',       // Vert clair
  accentLight: '#A7F3D0',
  danger: '#EF4444',
  dangerLight: '#FEE2E2',
  textMain: '#0F172A',
  textMuted: '#64748B',
  border: '#CBD5E1',
  surface: '#FFFFFF'
};

const Enrollment = ({ addNotification }) => {
  const [formData, setFormData] = useState({ name: '', email: '', level: '', filiere: '' });
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  const showMessage = (msg, type = 'info') => {
    setMessage(String(msg));
    setMessageType(type);

    if (type === 'success' || type === 'error') {
      setTimeout(() => setMessage(null), 5000);
    }
  };

  const handleFileSelect = (e) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    if (!selectedFile.type.startsWith("image/")) {
      showMessage("❌ Veuillez sélectionner une image valide", "error");
      return;
    }

    setFile(selectedFile);

    const reader = new FileReader();
    reader.onload = (event) => {
      if (typeof event.target?.result === 'string') {
        setPreview(event.target.result);
      }
    };
    reader.readAsDataURL(selectedFile);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const name = formData.name.trim();
    const email = formData.email?.trim() || null;
    const level = formData.level;
    const filiere = formData.filiere;

    if (!name || !file || !level || !filiere) {
       showMessage(" Nom, image, niveau et filière requis", "error");
      return;
    }

    setLoading(true);

    try {
      showMessage(" Envoi en cours...", "info");

      console.log("LEVEL:", level);
      console.log("FILIERE:", filiere);
      const response = await studentsAPI.enrollFromImage(
        name,
        email,
        file,
        level,
        filiere
      );

      if (response.success) {
        showMessage(` ${response.data.name} enrôlé avec succès !`, "success");
        addNotification(` ${response.data.name} enrôlé`, 'success');

        setFormData({ name: '', email: '', level: '', filiere: '' });
        setFile(null);
        setPreview(null);
      } else {
        throw new Error(response.error || "Erreur inconnue");
      }

    } catch (err) {
      const errorMsg = err.message || "Erreur serveur";
      showMessage(`❌ ${errorMsg}`, "error");
      addNotification(`❌ ${errorMsg}`, 'error');
    }

    setLoading(false);
  };

  const messageColors = {
    success: { bg: '#D1FAE5', text: '#166534' },
    error: { bg: '#FEE2E2', text: '#991B1B' },
    info: { bg: '#DBEAFE', text: '#1E40AF' }
  };

  const msgColor = messageColors[messageType];

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.header}>
          <h2 style={styles.title}>Enrôlement d'un étudiant</h2>
        </div>

        {message && (
          <div style={{
            ...styles.message,
            backgroundColor: msgColor.bg,
            color: msgColor.text
          }}>
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit} style={styles.form}>
          <input
            type="text"
            placeholder="Nom complet"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            style={styles.input}
            disabled={loading}
            required
          />

          <input
            type="email"
            placeholder="Email (optionnel)"
            value={formData.email}
            onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            style={styles.input}
            disabled={loading}
          />

          <select
            value={formData.level}
            onChange={(e) => setFormData({ ...formData, level: e.target.value })}
            style={styles.input}
            disabled={loading}
            required
          >
            <option value="">Sélectionner le niveau</option>
            <option value="L1">L1</option>
            <option value="L2">L2</option>
            <option value="L3">L3</option>
            <option value="M1">M1</option>
            <option value="M2">M2</option>
            <option value="D1">D1</option>
            <option value="D2">D2</option>
          </select>

          <input
            type="text"
            placeholder="Filière"
            value={formData.filiere}
            onChange={(e) => setFormData({ ...formData, filiere: e.target.value })}
            style={styles.input}
            disabled={loading}
            required
          />

          <input
            type="file"
            accept="image/*"
            onChange={handleFileSelect}
            disabled={loading}
            required
            style={styles.fileInput}
          />

          {preview && (
            <div style={styles.previewContainer}>
              <img
                src={preview}
                alt="preview"
                style={styles.preview}
              />
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              ...styles.button,
              opacity: loading ? 0.75 : 1,
              cursor: loading ? 'not-allowed' : 'pointer'
            }}
          >
            {loading ? "⏳ Traitement en cours..." : "Enrôler l'étudiant"}
          </button>
        </form>
      </div>
    </div>
  );
};

const styles = {
  container: {
    maxWidth: "560px",
    margin: "40px auto",
    padding: "20px"
  },
  card: {
    backgroundColor: COLORS.surface,
    borderRadius: "24px",
    overflow: "hidden",
    boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.18)",
    border: `1px solid ${COLORS.border}`
  },
  header: {
    background: `linear-gradient(135deg, ${COLORS.primary} 0%, #3B82F6 100%)`,
    padding: "32px 40px",
    color: "white"
  },
  title: {
    margin: 0,
    fontSize: "28px",
    fontWeight: "700",
    textAlign: "center"
  },
  form: {
    padding: "35px",
    display: "flex",
    flexDirection: "column",
    gap: "18px"
  },
  input: {
    padding: "14px 18px",
    borderRadius: "12px",
    border: `1px solid ${COLORS.border}`,
    fontSize: "15px",
    outline: "none",
    backgroundColor: "#F8FAFC"
  },
  fileInput: {
    width: "100%",
    padding: "14px",
    border: `2px dashed ${COLORS.accent}`,
    borderRadius: "12px",
    backgroundColor: "#F0FDF4",
    cursor: "pointer"
  },
  previewContainer: {
    borderRadius: "16px",
    overflow: "hidden",
    boxShadow: "0 15px 30px rgba(16, 185, 129, 0.25)",
    border: `2px solid ${COLORS.accentLight}`
  },
  preview: {
    width: "100%",
    borderRadius: "16px"
  },
  button: {
    padding: "16px",
    borderRadius: "14px",
    background: `linear-gradient(135deg, ${COLORS.primary} 0%, #2563EB 100%)`,
    color: "white",
    border: "none",
    fontSize: "16px",
    fontWeight: "600",
    marginTop: "10px",
    boxShadow: "0 10px 20px rgba(30, 64, 175, 0.3)"
  },
  message: {
    padding: "14px 18px",
    borderRadius: "10px",
    marginBottom: "20px",
    fontSize: "15px"
  }
};

export default Enrollment;
